#include <functional>
#include <future>
#include <memory>
#include <string>
#include <sstream>

#include <allegro_hand_interfaces/action/move_trajectory.hpp>
#include "allegro_hand/AllegroHand.h"


#include "rclcpp/rclcpp.hpp"
#include "rclcpp_action/rclcpp_action.hpp"

class MoveTrajectoryActionClient : public rclcpp::Node
{
public:
    using MoveTrajectory = allegro_hand_interfaces::action::MoveTrajectory;
    using GoalHandleMoveTrajectory = rclcpp_action::ClientGoalHandle<MoveTrajectory>;

    explicit MoveTrajectoryActionClient(const rclcpp::NodeOptions & options,
                                    const std::vector<AllegroHandDriver::Vector>& trajectory)
                                    // double percentage_vel)
    : Node("move_trajectory_action_client", options),
      trajectory_(trajectory)
    //   percentage_velocity_(percentage_vel)
    {
    this->client_ptr_ = rclcpp_action::create_client<MoveTrajectory>(
        this,
        "/move_trajectory");
    this->timer_ = this->create_wall_timer(
        std::chrono::milliseconds(500),
        std::bind(&MoveTrajectoryActionClient::send_goal_move_trajectory, this));
    }

    void send_goal_move_trajectory()
    {
        using namespace std::placeholders;

        this->timer_->cancel();

        if (!this->client_ptr_->wait_for_action_server()) {
            RCLCPP_ERROR(this->get_logger(), "Action server not available after waiting");
            rclcpp::shutdown();
        }

        auto goal_msg = MoveTrajectory::Goal();
        goal_msg.trajectory.resize(trajectory_.size());
        for (long unsigned int i=0; i < trajectory_.size(); i++){
            goal_msg.trajectory[i].hand_configuration.resize(16);
            for (int ii=0; ii < 16; ii ++){
                goal_msg.trajectory[i].hand_configuration[ii] = trajectory_[i](ii);
            }
        }
        // goal_msg.percentage_velocity = percentage_velocity_;

        RCLCPP_INFO(this->get_logger(), "Sending goal");

        auto send_goal_options = rclcpp_action::Client<MoveTrajectory>::SendGoalOptions();
        send_goal_options.goal_response_callback =
            std::bind(&MoveTrajectoryActionClient::goal_response_callback, this, _1);
        send_goal_options.feedback_callback =
            std::bind(&MoveTrajectoryActionClient::feedback_callback, this, _1, _2);
        send_goal_options.result_callback =
            std::bind(&MoveTrajectoryActionClient::result_callback, this, _1);
        this->client_ptr_->async_send_goal(goal_msg, send_goal_options);
    }

private:
    rclcpp_action::Client<MoveTrajectory>::SharedPtr client_ptr_;
    rclcpp::TimerBase::SharedPtr timer_;
    std::vector<AllegroHandDriver::Vector> trajectory_;
    // double percentage_velocity_;

    void goal_response_callback(const GoalHandleMoveTrajectory::SharedPtr & goal_handle)
    {
        if (!goal_handle) {
            RCLCPP_ERROR(this->get_logger(), "Goal was rejected by server");
        } else {
            RCLCPP_INFO(this->get_logger(), "Goal accepted by server, waiting for result");
        }
    }

    void feedback_callback(
    GoalHandleMoveTrajectory::SharedPtr,
    const std::shared_ptr<const MoveTrajectory::Feedback> feedback)
    {
        std::stringstream ss;
        ss << "Current configuration: " << feedback->current_configuration.header.frame_id << ". Position: ";
        for (auto number : feedback->current_configuration.position) {
            ss << number << " ";
        }
        ss << "\n Desired configuration: " << feedback->desired_current_configuration.header.frame_id << ". Position: ";
        for (auto number : feedback->desired_current_configuration.position) {
            ss << number << " ";
        }
        RCLCPP_INFO(this->get_logger(), ss.str().c_str());

    }

    void result_callback(const GoalHandleMoveTrajectory::WrappedResult & result)
    {
        switch (result.code) {
            case rclcpp_action::ResultCode::SUCCEEDED:
            break;
            case rclcpp_action::ResultCode::ABORTED:
            RCLCPP_ERROR(this->get_logger(), "Goal was aborted");
            return;
            case rclcpp_action::ResultCode::CANCELED:
            RCLCPP_ERROR(this->get_logger(), "Goal was canceled");
            return;
            default:
            RCLCPP_ERROR(this->get_logger(), "Unknown result code");
            return;
        }
        std::stringstream ss;
        if(result.result->status){
            ss << "The move_trajectory action has been completed succesfully: ";
        } else{
            ss << "The move_trajectory action has failed ";
        }
        
        RCLCPP_INFO(this->get_logger(), ss.str().c_str());
        rclcpp::shutdown();
    }
};  

